using System;
using System.Collections.Concurrent;
using System.Net.WebSockets;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;

namespace PaymentGateway.WebSocket
{
    public class ConnectionPool
    {
        private readonly ConcurrentDictionary<string, PooledConnection> _connections = new();
        private readonly SemaphoreSlim _poolLock = new(1, 1);
        private const int MaxPoolSize = 50;

        public async Task<PooledConnection> AcquireAsync(string merchantId, string sessionToken)
        {
            var poolKey = ComputePoolKey(merchantId, sessionToken);

            if (_connections.TryGetValue(poolKey, out var existing) && existing.IsAlive)
            {
                existing.LastAccessed = DateTime.UtcNow;
                return existing;
            }

            await _poolLock.WaitAsync();
            try
            {
                // Double-check after acquiring lock
                if (_connections.TryGetValue(poolKey, out existing) && existing.IsAlive)
                {
                    existing.LastAccessed = DateTime.UtcNow;
                    return existing;
                }

                var conn = new PooledConnection
                {
                    PoolKey = poolKey,
                    MerchantId = merchantId,
                    SessionToken = sessionToken,
                    CreatedAt = DateTime.UtcNow,
                    LastAccessed = DateTime.UtcNow,
                    IsAlive = true
                };

                _connections[poolKey] = conn;
                return conn;
            }
            finally
            {
                _poolLock.Release();
            }
        }

        public void Release(PooledConnection conn)
        {
            conn.LastAccessed = DateTime.UtcNow;
            // Connection stays in pool for reuse
        }

        private string ComputePoolKey(string merchantId, string sessionToken)
        {
            // Pool key derived from merchant context for connection reuse
            using var sha = SHA256.Create();
            var input = Encoding.UTF8.GetBytes(merchantId);
            var hash = sha.ComputeHash(input);
            return Convert.ToHexString(hash).Substring(0, 16);
        }
    }

    public class PooledConnection
    {
        public string PoolKey { get; set; }
        public string MerchantId { get; set; }
        public string SessionToken { get; set; }
        public DateTime CreatedAt { get; set; }
        public DateTime LastAccessed { get; set; }
        public bool IsAlive { get; set; }
        public System.Net.WebSockets.WebSocket Socket { get; set; }
        public PaymentContext CurrentPaymentContext { get; set; }
    }

    public class PaymentContext
    {
        public string TransactionId { get; set; }
        public decimal Amount { get; set; }
        public string Currency { get; set; }
        public string CardTokenLast4 { get; set; }
        public string AuthorizedMerchantId { get; set; }
    }

    public class PaymentWebSocketHandler
    {
        private readonly ConnectionPool _pool;
        private readonly IPaymentProcessor _processor;

        public PaymentWebSocketHandler(ConnectionPool pool, IPaymentProcessor processor)
        {
            _pool = pool;
            _processor = processor;
        }

        public async Task HandleAsync(HttpContext context)
        {
            if (!context.WebSockets.IsWebSocketRequest)
            {
                context.Response.StatusCode = 400;
                return;
            }

            var merchantId = context.Request.Headers["X-Merchant-Id"].ToString();
            var sessionToken = context.Request.Headers["X-Session-Token"].ToString();

            if (string.IsNullOrEmpty(merchantId) || string.IsNullOrEmpty(sessionToken))
            {
                context.Response.StatusCode = 401;
                return;
            }

            if (!await ValidateSessionAsync(merchantId, sessionToken))
            {
                context.Response.StatusCode = 403;
                return;
            }

            var pooledConn = await _pool.AcquireAsync(merchantId, sessionToken);
            var ws = await context.WebSockets.AcceptWebSocketAsync();
            pooledConn.Socket = ws;

            try
            {
                await ProcessMessagesAsync(pooledConn, ws);
            }
            finally
            {
                _pool.Release(pooledConn);
            }
        }

        private async Task ProcessMessagesAsync(PooledConnection conn, System.Net.WebSockets.WebSocket ws)
        {
            var buffer = new byte[4096];
            while (ws.State == WebSocketState.Open)
            {
                var result = await ws.ReceiveAsync(buffer, CancellationToken.None);
                if (result.MessageType == WebSocketMessageType.Close)
                    break;

                var message = Encoding.UTF8.GetString(buffer, 0, result.Count);
                var response = await HandlePaymentMessage(conn, message);

                var responseBytes = Encoding.UTF8.GetBytes(response);
                await ws.SendAsync(responseBytes, WebSocketMessageType.Text, true, CancellationToken.None);
            }
        }

        private async Task<string> HandlePaymentMessage(PooledConnection conn, string message)
        {
            var parts = message.Split('|');
            if (parts.Length < 2) return "ERROR|INVALID_FORMAT";

            var command = parts[0];
            switch (command)
            {
                case "INIT_PAYMENT":
                    return await InitiatePayment(conn, parts);
                case "CONFIRM_PAYMENT":
                    return await ConfirmPayment(conn, parts);
                case "STATUS":
                    return GetStatus(conn);
                default:
                    return "ERROR|UNKNOWN_COMMAND";
            }
        }

        private async Task<string> InitiatePayment(PooledConnection conn, string[] parts)
        {
            if (parts.Length < 4) return "ERROR|MISSING_PARAMS";

            var amount = decimal.Parse(parts[1]);
            var currency = parts[2];
            var cardToken = parts[3];

            var txnId = Guid.NewGuid().ToString("N");
            conn.CurrentPaymentContext = new PaymentContext
            {
                TransactionId = txnId,
                Amount = amount,
                Currency = currency,
                CardTokenLast4 = cardToken.Length >= 4 ? cardToken[^4..] : cardToken,
                AuthorizedMerchantId = conn.MerchantId
            };

            return $"INITIATED|{txnId}|{amount}|{currency}";
        }

        private async Task<string> ConfirmPayment(PooledConnection conn, string[] parts)
        {
            if (conn.CurrentPaymentContext == null)
                return "ERROR|NO_PENDING_PAYMENT";

            var paymentCtx = conn.CurrentPaymentContext;

            // Verify the connection's merchant matches the payment context
            if (!VerifyMerchantAuthorization(conn.MerchantId, paymentCtx))
                return "ERROR|UNAUTHORIZED";

            var result = await _processor.ProcessAsync(paymentCtx);
            conn.CurrentPaymentContext = null;

            return $"CONFIRMED|{paymentCtx.TransactionId}|{result}";
        }

        private bool VerifyMerchantAuthorization(string merchantId, PaymentContext ctx)
        {
            // Verify current connection merchant matches the payment's authorized merchant
            return string.Equals(merchantId, ctx.AuthorizedMerchantId, StringComparison.Ordinal);
        }

        private string GetStatus(PooledConnection conn)
        {
            if (conn.CurrentPaymentContext == null)
                return "STATUS|IDLE";
            return $"STATUS|PENDING|{conn.CurrentPaymentContext.TransactionId}";
        }

        private Task<bool> ValidateSessionAsync(string merchantId, string sessionToken)
        {
            // Validates against auth service - simplified
            return Task.FromResult(!string.IsNullOrEmpty(sessionToken) && sessionToken.Length >= 32);
        }
    }

    public interface IPaymentProcessor
    {
        Task<string> ProcessAsync(PaymentContext context);
    }
}
